import itertools


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    initial = (source, initial_mask, 0)
    start = data["start"]
    best = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    coupons = data["coupons"]
    deadline = data["deadline"]

    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full and
                (coupon_rule == "at_most" or used == coupons)):
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                discounted = max(minimum_duration,
                                 edge["duration"] - edge.get("discount", 0))
                options.append((discounted, used + 1))
            for duration, next_used in options:
                next_time = depart + duration
                if next_time > deadline:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < best.get(next_state, float("inf")):
                    best[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node,
                                           next_mask, next_used))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = (event.get("account", "default") + "|" +
               event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    initial_constraints = {name: [tuple(bounds)]
                          for name, bounds in data["roots"].items()}
    best_vector = None
    best_versions = None

    def acyclic(edges):
        done = set()
        active = set()

        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(other) for other in edges.get(name, ())):
                return False
            active.remove(name)
            done.add(name)
            return True

        return all(visit(name) for name in edges)

    def search(chosen, constraints, edges):
        nonlocal best_vector, best_versions
        unresolved = [name for name in constraints if name not in chosen]
        if not unresolved:
            if not acyclic(edges):
                return
            names = sorted(packages, reverse=True)
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_versions = dict(chosen)
            return

        name = unresolved[0]
        allowed = constraints[name]
        rows = []
        for row in packages.get(name, []):
            version = row["version"]
            if any(not (low <= version <= high) for low, high in allowed):
                continue
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            rows.append(row)

        for row in rows:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_constraints = {key: list(value)
                                for key, value in constraints.items()}
            next_edges = {key: list(value) for key, value in edges.items()}
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                dep_name = dep["name"]
                deps.append(dep_name)
                next_constraints.setdefault(dep_name, []).append(
                    (dep["min"], dep["max"]))
                if dep_name in next_chosen and not (
                        dep["min"] <= next_chosen[dep_name] <= dep["max"]):
                    break
            else:
                next_edges[name] = deps
                search(next_chosen, next_constraints, next_edges)

    search({}, initial_constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _quotas(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    if mandatory & blocked:
        return {"error": "impossible"}
    options = [job for job in jobs if job["id"] not in blocked]
    k = data["k"]
    best_value = None
    best_ids = None

    for subset in itertools.combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        end = None
        feasible = True
        for job in ordered:
            if end is not None and job["start"] < end:
                feasible = False
                break
            end = job["end"]
        if not feasible:
            continue

        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not (bounds[0] <= counts.get(group, 0) <= bounds[1])
               for group, bounds in data.get("quotas", {}).items()):
            continue

        value = sum(job["value"] for job in subset)
        id_list = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and id_list < best_ids)):
            best_value = value
            best_ids = id_list

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


